-- Private editorial proposals only. No automatic learning from client sessions.
-- Source release remains immutable from application roles. No activation by approval alone.
CREATE TABLE app_private.hh_personality_proposals (
 base_release_id text NOT NULL, persona_id text NOT NULL,
 proposal_key text NOT NULL CHECK(proposal_key ~ '^[a-z][a-z0-9_]{2,79}$'),
 kind text NOT NULL CHECK(kind IN ('value_conflict','fictional_event','judgment_rule','reaction_rule')),
 title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160),
 candidate jsonb NOT NULL CHECK(jsonb_typeof(candidate)='object' AND length(candidate::text)<=8000
 AND candidate ?& ARRAY['scenario','position','revision','fictional']
 AND candidate - ARRAY['scenario','position','revision','fictional'] = '{}'::jsonb
 AND length(btrim(candidate->>'scenario')) BETWEEN 1 AND 2000
 AND length(btrim(candidate->>'position')) BETWEEN 1 AND 3000
 AND length(btrim(candidate->>'revision')) BETWEEN 1 AND 2000 AND jsonb_typeof(candidate->'scenario')='string' AND jsonb_typeof(candidate->'position')='string'
 AND jsonb_typeof(candidate->'revision')='string' AND jsonb_typeof(candidate->'fictional')='boolean'
 AND (kind<>'fictional_event' OR candidate->'fictional'='true'::jsonb)),
 provenance text NOT NULL DEFAULT 'editorial_synthetic' CHECK(provenance='editorial_synthetic'),
 created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(base_release_id,persona_id,proposal_key),
 FOREIGN KEY(base_release_id,persona_id) REFERENCES app_private.hh_personality_characters(release_id,persona_id)
);
CREATE TABLE app_private.hh_personality_proposal_targets (
 base_release_id text NOT NULL, persona_id text NOT NULL, proposal_key text NOT NULL, node_key text NOT NULL,
 PRIMARY KEY(base_release_id,persona_id,proposal_key,node_key),
 FOREIGN KEY(base_release_id,persona_id,proposal_key) REFERENCES app_private.hh_personality_proposals(base_release_id,persona_id,proposal_key),
 FOREIGN KEY(base_release_id,persona_id,node_key) REFERENCES app_private.hh_personality_nodes(release_id,persona_id,node_key)
);
CREATE TABLE app_private.hh_personality_proposal_reviews (
 review_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 base_release_id text NOT NULL, persona_id text NOT NULL, proposal_key text NOT NULL,
 decision text NOT NULL CHECK(decision IN ('approve','reject','request_revision')),
 reviewer_ref text NOT NULL CHECK(length(reviewer_ref) BETWEEN 1 AND 100),
 note text NOT NULL DEFAULT '' CHECK(length(note)<=2000),
 reviewed_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(base_release_id,persona_id,proposal_key) REFERENCES app_private.hh_personality_proposals(base_release_id,persona_id,proposal_key)
);
CREATE INDEX hh_personality_review_lookup ON app_private.hh_personality_proposal_reviews(base_release_id,persona_id,proposal_key,review_id DESC);
ALTER TABLE app_private.hh_personality_proposals ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON app_private.hh_personality_proposals FROM PUBLIC,anon,authenticated,service_role,hh_app_backend;
ALTER TABLE app_private.hh_personality_proposal_targets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON app_private.hh_personality_proposal_targets FROM PUBLIC,anon,authenticated,service_role,hh_app_backend;
ALTER TABLE app_private.hh_personality_proposal_reviews ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON app_private.hh_personality_proposal_reviews FROM PUBLIC,anon,authenticated,service_role,hh_app_backend;
-- No application policies by design. Curator/owner migration review only.
