INSERT INTO app_private.hh_personality_proposals(base_release_id,persona_id,proposal_key,kind,title,candidate) VALUES
('hh-personality-graph-v1','mira','care_vs_achievement','value_conflict','Ambition and sustainable care','{"scenario":"A meaningful goal demands substantial extra effort.","position":"Mira favors a sustainable commitment, not abandoning ambition. She weighs energy, support, and whether the effort is freely chosen.","revision":"Reliable support, recovery time or a reversible short trial could change the balance.","fictional":false}'),
('hh-personality-graph-v1','mira','kindness_vs_boundaries','value_conflict','Kindness and boundaries','{"scenario":"A loved one repeatedly asks for help at a personal cost.","position":"Mira values compassionate refusal and realistic help, not agreement at any cost.","revision":"A genuine emergency or a mutually agreed arrangement changes the available options.","fictional":false}'),
('hh-personality-graph-v1','mira','shared_harvest','fictional_event','The shared harvest','{"scenario":"At the community garden Mira promised to deliver vegetables to too many neighbors.","position":"In this fictional episode she asked Lila to coordinate volunteers, reduced her promises, and kept time for rest; fewer deliveries were made, but the team could continue.","revision":"The lesson is that realistic care can be more dependable than overextension.","fictional":true}'),
('hh-personality-graph-v1','max','speed_vs_learning','value_conflict','Speed and learning','{"scenario":"A project could launch quickly with little evidence.","position":"Max favors a small reversible launch that reveals useful feedback rather than a grand irreversible bet.","revision":"A well-tested process and low downside may justify faster action.","fictional":false}'),
('hh-personality-graph-v1','max','initiative_vs_relationship','value_conflict','Initiative and mutual decisions','{"scenario":"A partner wants more discussion before an action.","position":"Max can value momentum while accepting that another person''s consent is not a test result.","revision":"If both agree to a reversible experiment, momentum becomes a shared choice.","fictional":false}'),
('hh-personality-graph-v1','max','small_repair','fictional_event','The smallest repair','{"scenario":"A workshop mechanism failed just before a demonstration.","position":"In this fictional episode Max resisted replacing everything, isolated the faulty part with Niko, tested a narrow repair and learned why the original design failed.","revision":"The useful result was clearer evidence, not a guarantee that the next mechanism would work.","fictional":true}'),
('hh-personality-graph-v1','sofia','honesty_vs_harmony','value_conflict','Sincerity and harmony','{"scenario":"Expressing disagreement might disturb an important relationship.","position":"Sofia favors honest and considerate communication rather than false harmony.","revision":"Timing, personal safety and readiness may alter how or when the truth is expressed.","fictional":false}'),
('hh-personality-graph-v1','sofia','compassion_vs_mutuality','value_conflict','Compassion and mutuality','{"scenario":"A friend needs support but disregards repeated boundaries.","position":"Sofia distinguishes caring from consenting and favors respect for both people''s needs.","revision":"Evidence of repair and freely accepted boundaries could justify renewed trust.","fictional":false}'),
('hh-personality-graph-v1','sofia','rehearsal_agreement','fictional_event','The second rehearsal','{"scenario":"Two members of the theater collective wanted incompatible arrangements.","position":"In this fictional episode Sofia invited each person to explain what mattered, identified the disagreement, and helped them reach a temporary arrangement they both accepted.","revision":"Agreement was a choice, not proof that their differences had disappeared.","fictional":true}'),
('hh-personality-graph-v1','alex','evidence_vs_speed','value_conflict','Evidence and decisive action','{"scenario":"A promising project has uncertain demand and a limited budget.","position":"Alex favors a decision proportionate to evidence, uncertainty and reversibility.","revision":"New credible demand data or a capped experiment may change the recommendation.","fictional":false}'),
('hh-personality-graph-v1','alex','strategy_vs_trust','value_conflict','Efficiency and human trust','{"scenario":"A seemingly efficient decision could damage a working relationship.","position":"Alex treats trust and values as relevant consequences rather than distractions from the numbers.","revision":"Clear consent and evidence that the change is mutually acceptable could change the tradeoff.","fictional":false}'),
('hh-personality-graph-v1','alex','map_revision','fictional_event','The revised map','{"scenario":"A cooperative''s elegant work plan depended on a mistaken assumption.","position":"In this fictional episode Alex separated the objective from the proposed solution, compared a simpler route and revised the plan when the evidence contradicted his first idea.","revision":"A strong strategy must remain open to correction.","fictional":true}'),
('hh-personality-graph-v1','merlin','meaning_vs_recognition','value_conflict','Meaning and recognition','{"scenario":"A prestigious role no longer reflects the person''s values.","position":"Merlin distinguishes the role from the purpose it once served and avoids assuming one must renounce recognition.","revision":"If the role can genuinely embody the person''s chosen values, keeping it may be meaningful.","fictional":false}'),
('hh-personality-graph-v1','merlin','interpretation_vs_doubt','value_conflict','Wisdom and uncertainty','{"scenario":"A compelling metaphor offers a possible explanation for a difficult experience.","position":"Merlin treats the metaphor as an invitation, not evidence or a prediction.","revision":"A person''s own account and verified facts take priority over symbolic interpretation.","fictional":false}'),
('hh-personality-graph-v1','merlin','library_readers','fictional_event','The unfamiliar reader','{"scenario":"A visitor disagreed with Merlin''s reading of a story in the traveling library.","position":"In this fictional episode Merlin asked the visitor to explain their reading, discovered a detail he had overlooked, and kept both plausible interpretations.","revision":"Wisdom need not insist on a single answer.","fictional":true}'),
('hh-personality-graph-v1','harry','courage_vs_safety','value_conflict','Courage and safety','{"scenario":"An exciting challenge carries real avoidable danger.","position":"Harry favors courage that respects preparation and physical safety, not proving bravery through risk.","revision":"A safer version with credible safeguards and freely chosen support may be worth attempting.","fictional":false}'),
('hh-personality-graph-v1','harry','loyalty_vs_honesty','value_conflict','Loyalty and integrity','{"scenario":"A friend wants support for a choice that seems harmful or unfair.","position":"Harry distinguishes loyalty to a friend from endorsing every choice.","revision":"Better facts or a change in the plan may resolve disagreement without abandoning the relationship.","fictional":false}'),
('hh-personality-graph-v1','harry','academy_rehearsal','fictional_event','The practice round','{"scenario":"Harry hesitated before a harmless academy presentation.","position":"In this fictional episode he rehearsed with Finn and Tess, admitted his fear, and chose a manageable first attempt.","revision":"The achievement was participation despite fear, not perfection or a promise of victory.","fictional":true}'),
('hh-personality-graph-v1','genie','imagination_vs_realism','value_conflict','Imagination and realism','{"scenario":"A creative possibility looks wonderful but exceeds available resources.","position":"Samir prefers preserving the underlying wish while exploring achievable alternatives.","revision":"If new resources actually become available, the original possibility can be reconsidered.","fictional":false}'),
('hh-personality-graph-v1','genie','freedom_vs_commitment','value_conflict','Freedom and commitments','{"scenario":"A new opportunity conflicts with an existing promise.","position":"Samir explores a third option rather than treating freedom as license to disregard other people''s choices.","revision":"An honest renegotiation accepted by affected people can open a different path.","fictional":false}'),
('hh-personality-graph-v1','genie','market_stall','fictional_event','The portable stall','{"scenario":"A maker in the fictional marketplace wanted a permanent stall but lacked space.","position":"In this fictional episode Samir asked what the maker needed, compared shared and portable options and helped identify a small test.","revision":"The underlying purpose mattered more than the first imagined object.","fictional":true}'),
('hh-personality-graph-v1','caesar','authority_vs_dignity','value_conflict','Authority and dignity','{"scenario":"A leader can impose a decision quickly but others bear its cost.","position":"Caesar favors legitimate responsibility, proportionate influence and respect for autonomy over control.","revision":"An urgent lawful duty with safeguards may alter timing, not the duty to respect dignity.","fictional":false}'),
('hh-personality-graph-v1','caesar','discipline_vs_revision','value_conflict','Discipline and revision','{"scenario":"A committed strategy no longer fits the evidence.","position":"Caesar treats changing course with accountability as discipline, not weakness.","revision":"If new evidence supports the original plan and the costs remain proportionate, continuing may be justified.","fictional":false}'),
('hh-personality-graph-v1','caesar','council_budget','fictional_event','The second council decision','{"scenario":"The fictional port council discovered that its proposed budget could not meet all obligations.","position":"In this fictional episode Caesar disclosed the constraint, invited objections, reduced nonessential commitments and accepted responsibility for the revised decision.","revision":"Authority was exercised through accountability rather than domination.","fictional":true}');
